CREATE TABLE `owner_statements` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `doc_no` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statement_date` date DEFAULT NULL,
  `owner` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stat_bills` int NOT NULL DEFAULT '0',
  `stat_debt` decimal(16,2) NOT NULL DEFAULT '0.00',
  `stat_paid` decimal(16,2) NOT NULL DEFAULT '0.00',
  `stat_remaining` decimal(16,2) NOT NULL DEFAULT '0.00',
  `paid_count` int NOT NULL DEFAULT '0',
  `paid_sum` decimal(16,2) NOT NULL DEFAULT '0.00',
  `remaining_count` int NOT NULL DEFAULT '0',
  `remaining_sum` decimal(16,2) NOT NULL DEFAULT '0.00',
  `items_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_owner` (`owner`),
  KEY `idx_date` (`statement_date`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
